      cell.style.fill = 'hsl(' + (210 + 80 * hue).toFixed(0) + ', 55%, ' + (55 + 10 * Math.sin(r + c)).toFixed(0) + '%)';
      p0.appendChild(cell);
      cells.push({ n: cell, hole: r >= 1 && r <= 3 && c >= 2 && c <= 4 });
