    label(p3, R, 146, '只给一句话：文字控制', 'demo-x-ink', 14);
    chip(p3, R, 164, RW, '“the person walks normally”', C_TXT, { size: 12, left: true });
    label(p3, R, 226, '一个关节都不给，也要补出全身', 'demo-x-ink2', 12);
