  /* ── scene 6: 训练场、提前终止与优先采样（第 5.4、5.5 节，图 4） ── */
  function buildScenePlayground() {
    var s = sceneSvg('左边是论文图 4 的训练场：平地、不平地形、物体区三块，旁白念到哪块就框出哪块；右边依次讲出生位置、' +
      '提前终止（一条关节误差曲线碰到 0.25 m 或 0.5 m 的线就结束）、按失败率优先采样（玩具示意）与只算平地上的失败');
    var fig = paperFig(s, 'fig4_playground.webp', 20, 36, 352, 360, '论文图 4：训练场（截图）', { ar: 900 / 916, pad: 3 });
    function boxOn(v0, v1, color) {
      var a = fig.px(0, v0), b = fig.px(1, v1);
      var r = paint(svgEl('rect', { x: a[0] - 2, y: a[1] - 1, width: b[0] - a[0] + 4, height: b[1] - a[1] + 2, rx: 6, fill: 'none', 'stroke-width': 3.2 }), null, color);
      s.appendChild(r);
      return r;
    }
    var regions = [boxOn(0, 0.335, C_ACCENT), boxOn(0.337, 0.668, C_WARN), boxOn(0.67, 1, C_BAD)];
    var R = 396, RW = 384;
    var p1 = group(s);
    label(p1, R, 64, '训练场分三块', 'demo-x-ink', 14);
    chip(p1, R, 82, RW, '平地：数据多半在平地上录，先照原样做', C_ACCENT, { size: 12, left: true });
    chip(p1, R, 118, RW, '不平地形：台阶、碎石、平滑和粗糙的坡', C_WARN, { size: 12, left: true });
    chip(p1, R, 154, RW, '物体区：椅子、桌子、沙发摆在平地上', C_BAD, { size: 12, left: true });
    var p2 = group(s);
    label(p2, R, 64, '在哪儿出生', 'demo-x-ink', 14);
    chip(p2, R, 82, RW, '不带物体的动作：平地或不平地形，位置随机', C_WARN, { size: 12, left: true });
    chip(p2, R, 118, RW, '带物体交互的动作：只在物体区', C_BAD, { size: 12, left: true });
    label(p2, R, 182, '物体区里没有坑洼，交互动作练得干净、可复现', 'demo-x-ink2', 12);
    var p3 = group(s);
    label(p3, R, 64, '提前终止：偏太多就重来', 'demo-x-ink', 14);
    var EX0 = R + 30, EY0 = 96, EW = 330, EH = 150;
    hline(p3, EX0, EY0 + EH, EX0 + EW, EY0 + EH, C_BORDER, 1.2); hline(p3, EX0, EY0, EX0, EY0 + EH, C_BORDER, 1.2);
    function ey(v) { return EY0 + EH * (1 - v / 0.6); }
    hline(p3, EX0, ey(0.25), EX0 + EW, ey(0.25), C_ACCENT, 1.6, '6 4');
    hline(p3, EX0, ey(0.5), EX0 + EW, ey(0.5), C_WARN, 1.6, '6 4');
    label(p3, EX0 + EW, ey(0.25) - 5, '平地 0.25 m', 'demo-x-ink2', 10.5, 'end');
    label(p3, EX0 + EW, ey(0.5) - 5, '不平地形 0.5 m', 'demo-x-ink2', 10.5, 'end');
    label(p3, EX0 - 6, ey(0) + 4, '0', 'demo-x-mut', 10, 'end');
    label(p3, EX0 + EW / 2, EY0 + EH + 18, '时间 →（任一关节的位置误差，示意）', 'demo-x-mut', 10, 'middle');
    var errCurve = pathLine(p3, [], C_BAD, 2.2), endMk = label(p3, 0, 0, '', 'demo-x-ink', 11);
    var p4 = group(s);
    label(p4, R, 64, '优先采样：越容易失败，越常练', 'demo-x-ink', 14);
    var TOY = [['走路', 0.001], ['跑步', 0.01], ['侧手翻', 0.08], ['后空翻', 0.3], ['霹雳舞', 0.45]];
    var wsum = TOY.reduce(function (a, r) { return a + Math.max(r[1], 3e-3); }, 0);
    var tRows = TOY.map(function (r, i) { return barRowAt(p4, R, 84 + i * 30, 70, r[0], C_WARN, 18, 11.5); });
    rich(p4, R, 248, '概率 ∝ 失败率，下限 $3 \\times 10^{-3}$（玩具示意）', 11.5, 'demo-x-mut');
    var p5 = group(s);
    label(p5, R, 64, '只算平地上的失败', 'demo-x-ink', 14);
    chip(p5, R, 82, RW, '平地上失败 → 计入优先采样', C_GOOD, { size: 12, left: true });
    chip(p5, R, 118, RW, '前空翻上楼梯失败 → 不计：本来就不该成功', C_BAD, { size: 12, left: true });
    label(p5, R, 182, '这样难动作（后空翻、侧手翻）才能攒够数据', 'demo-x-ink2', 12);
    function draw(t, clock) {
      var now = nowOf(t, clock), ph = phase(t);
      var hot = ph <= 2 ? [ph === 0 ? Math.floor((now * 0.9) % 3) : -1, ph === 1 ? 1 : -1, ph === 1 ? 2 : -1] : [];
      regions.forEach(function (r, i) {
        var on = ph === 0 ? (Math.floor((now * 0.9) % 3) === i ? 1 : 0.15) : ph === 1 ? (i >= 1 ? 1 : 0.15) : 0;
        r.style.opacity = (on * (ph <= 1 ? 1 : 0)).toFixed(2);
      });
      void hot;
      /* 一条误差曲线：慢慢变大，碰到 0.25 m（平地）就结束，从头再来 */
      var cyc = now % 4, pts = [], hit = -1;
      for (var u = 0; u <= 60; u++) {
        var tt = 4 * u / 60; if (tt > cyc) break;
        var v = 0.04 + 0.05 * tt + 0.035 * Math.sin(3.1 * tt) + 0.012 * tt * tt;
        pts.push([EX0 + EW * u / 60, ey(Math.min(v, 0.58))]);
        if (v >= 0.25 && hit < 0) { hit = u; break; }
      }
      setPath(errCurve, pts);
      if (hit >= 0) { var q = pts[pts.length - 1]; endMk.setAttribute('x', (q[0] + 6).toFixed(1)); endMk.setAttribute('y', (q[1] - 8).toFixed(1)); endMk.textContent = '结束，换一段'; }
      else endMk.textContent = '';
      var grow = ease(seg(t, 10.6, 12.0));
      tRows.forEach(function (r, i) { var w = Math.max(TOY[i][1], 3e-3) / wsum; r.set(230 * w / 0.53 * grow, f1(100 * w) + '%'); });
      setOpacity(p1, win(t, 0.3, 3.6));
      setOpacity(p2, win(t, 3.6, 7.0));
      setOpacity(p3, win(t, 7.0, 10.4));
      setOpacity(p4, win(t, 10.4, 13.4));
      setOpacity(p5, win(t, 13.4));
    }
    return { el: s, draw: draw };
  }

