  /* ── scene 8: 为什么要 VAE（第 6.2 节） ── */
  /* 玩具：俯视图上从 S 到 T，中间一根柱子；老师的示范一半从上绕、一半从下绕 */
  var TOY = { sx: 70, sy: 210, tx: 350, ty: 210, ox: 210, oy: 210, or: 34 };
  function toyPath(z) {
    /* z > 0 从上绕，z < 0 从下绕；|z| 越大绕得越远 */
    var pts = [], bend = (z >= 0 ? -1 : 1) * (62 + 26 * Math.min(1.5, Math.abs(z)));
    for (var u = 0; u <= 40; u++) {
      var a = u / 40, x = TOY.sx + (TOY.tx - TOY.sx) * a, y = TOY.sy + bend * Math.sin(Math.PI * a);
      pts.push([x, y]);
    }
    return pts;
  }
